import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    best_count = 0
    best_len = 0
    best_sub = ""

    # Generate all non-empty substrings
    substrings = set()
    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings.add(s[i:j])

    for sub in substrings:
        count = 0
        start = 0
        while True:
            idx = s.find(sub, start)
            if idx == -1:
                break
            count += 1
            start = idx + 1

        # Check if this substring is better than the current best
        if count > best_count:
            best_count = count
            best_len = len(sub)
            best_sub = sub
        elif count == best_count:
            if len(sub) > best_len:
                best_len = len(sub)
                best_sub = sub
            elif len(sub) == best_len:
                if sub > best_sub:
                    best_sub = sub

    print(best_sub)

if __name__ == "__main__":
    solve()
